-- veymandoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Thaa Atoll, Central Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,900 residents"},{"label":"Size","value":"1.7 km long, 1.0 km wide"},{"label":"Distance from Male","value":"207 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Incredible culture, gorgeous beaches, excellent snorkeling"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, snorkelers, adventure seekers"}],"island_overview":["Veymandoo Island is an incredible local island in Thaa Atoll that offers visitors a vibrant glimpse into traditional Maldivian life. This amazing island combines natural beauty with an energetic atmosphere, providing an ideal destination for travelers seeking exciting cultural experiences and gorgeous tropical surroundings.","Known for its beautiful beaches, incredible coral reefs, and excellent marine biodiversity, Veymandoo provides wonderful opportunities for snorkeling, swimming, and underwater exploration. The island''s vibrant community embraces visitors with traditional Maldivian warmth and shares their dynamic way of life with incredible hospitality.","What makes Veymandoo special is its incredible natural environment and vibrant island setting. Visitors can enjoy gorgeous beaches, explore rich marine ecosystems, and experience dynamic island culture while staying in comfortable accommodations that showcase the incredible Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Veymandoo Island is beautifully located in the central part of Thaa Atoll, approximately 207 kilometers from Male. This location provides an incredible and vibrant experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to gorgeous coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Thaa Atoll in its most incredible form."]},{"heading":"Veymandoo: Incredible Paradise & Marine Vibrancy","paragraphs":["Veymandoo Island is blessed with exceptional natural beauty, featuring gorgeous white sand beaches, crystal-clear turquoise waters, and one of the most incredible marine environments in Thaa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in a vibrant, dynamic setting."]},{"heading":"Gorgeous White Sand Beaches","paragraphs":["Veymandoo features incredible white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and dynamic beach activities."]},{"heading":"Incredible House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers vibrant snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Vibrant Island Community","paragraphs":["Experience the dynamic spirit of traditional island life with friendly locals and incredible Maldivian culture in a vibrant community setting."]},{"heading":"Dynamic Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and incredible islands around Veymandoo for gorgeous tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Veymandoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Veymandoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Veymandoo offers a perfect blend of marine adventures, cultural experiences, and incredible activities. The island''s vibrant environment and dynamic atmosphere provide ideal conditions for various activities in a gorgeous, energetic setting."]},{"heading":"Incredible House Reef Snorkeling","paragraphs":["Explore the vibrant house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in incredible waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby gorgeous dive sites with professional dive operators offering guided dives and certification courses in incredible marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, gorgeous sandbanks, and discover the natural beauty of Thaa Atoll with vibrant exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in incredible community settings."]},{"heading":"Dynamic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience incredible Maldivian island life with vibrant cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy gorgeous sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in incredible waters."]},{"heading":"Community Life & Culture","paragraphs":["Veymandoo is home to approximately 1,900 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and incredible cultural traditions that create a vibrant atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Veymandoo follows traditional patterns centered around fishing, family, and community activities. The island maintains an incredible atmosphere where visitors can experience vibrant Maldivian culture and customs in their most dynamic, energetic setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this incredible island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Veymandoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and incredible cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Veymandoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Thaa Atoll."},{"question":"What is the best time to visit Veymandoo?","answer":"The best time to visit Veymandoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more incredible local atmosphere."},{"question":"What accommodation options are available on Veymandoo?","answer":"Veymandoo offers various accommodations including incredible guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in a vibrant setting."},{"question":"What makes Veymandoo''s vibrancy special?","answer":"Veymandoo is known for its incredible and vibrant natural environment. The island maintains traditional Maldivian cultural practices while offering a dynamic atmosphere perfect for energetic exploration. Visitors can experience exciting cultural exchanges and participate in incredible community activities."}],"island_nearby_slugs":["guraidhoo","gaadhiffushi","dhiyamigili","burunee","vilufushi","vandhoo","thimarafushi","omadhoo","madifushi","kinbidhoo","kandoodhoo","hirilandhoo"]}'::jsonb
where node_type = 'location' and slug = 'veymandoo';


-- veyvah
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Meemu Atoll, Central Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 500 residents"},{"label":"Size","value":"0.5 km long, 0.3 km wide"},{"label":"Distance from Male","value":"140 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Pristine beaches, hidden gem status, authentic culture"},{"label":"Best For","value":"Adventure seekers, snorkelers, culture enthusiasts, off-the-beaten-path travelers"}],"island_overview":["Veyvah Island is a hidden gem in Meemu Atoll that offers visitors an authentic and unspoiled glimpse into traditional Maldivian life. This charming island combines stunning natural beauty with rich cultural heritage, providing an ideal destination for travelers seeking genuine island experiences away from the crowds.","Known for its pristine beaches, crystal-clear waters, and vibrant house reef, Veyvah provides excellent opportunities for snorkeling, diving, and marine exploration. The island''s warm and welcoming community embraces visitors with traditional Maldivian hospitality and shares their authentic way of life with genuine enthusiasm.","What makes Veyvah special is its untouched natural beauty and authentic island atmosphere. Visitors can enjoy beautiful beaches, explore diverse marine life, and experience traditional island culture while staying in comfortable, family-run accommodations that offer genuine Maldivian experiences in an unspoiled setting."],"island_sections":[{"heading":"Location & Map","paragraphs":["Veyvah Island is located in the southern part of Meemu Atoll, approximately 140 kilometers from Male. The island''s remote position provides access to some of the most pristine and untouched marine environments in the atoll while maintaining an authentic, unspoiled atmosphere perfect for adventure and discovery.","The island''s location offers excellent protection from strong currents while providing access to vibrant coral reefs and diverse marine ecosystems. Its secluded position makes it an ideal destination for travelers seeking authentic experiences away from tourist crowds."]},{"heading":"Veyvah: Hidden Paradise & Marine Treasures","paragraphs":["Veyvah Island is blessed with exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and one of the most untouched marine environments in Meemu Atoll. The island offers perfect conditions for beach relaxation and marine exploration in an authentic, unspoiled setting."]},{"heading":"Pristine Untouched Beaches","paragraphs":["Veyvah features stunning white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and peaceful exploration."]},{"heading":"Pristine House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers exceptional snorkeling with diverse marine life and pristine coral formations."]},{"heading":"Authentic Cultural Experience","paragraphs":["Experience the genuine warmth of traditional island life with friendly locals and authentic Maldivian culture in an unspoiled environment."]},{"heading":"Hidden Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and pristine islands around Veyvah for the ultimate off-the-beaten-path tropical paradise experience."]},{"heading":"Beach Features","paragraphs":["Veyvah''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Veyvah feature:"]},{"heading":"Activities & Experiences","paragraphs":["Veyvah offers a perfect blend of marine adventures, cultural experiences, and exploration opportunities. The island''s pristine environment and authentic atmosphere provide ideal conditions for various activities in an unspoiled, traditional setting."]},{"heading":"Pristine House Reef Snorkeling","paragraphs":["Explore the pristine house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in untouched waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby pristine dive sites with professional dive operators offering guided dives and certification courses in untouched marine environments."]},{"heading":"Hidden Island Adventures","paragraphs":["Visit nearby uninhabited islands, pristine sandbanks, and discover the hidden beauty of Meemu Atoll''s most secluded spots."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in pristine waters."]},{"heading":"Authentic Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience authentic Maldivian island life in an unspoiled setting."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magical sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in pristine waters."]},{"heading":"Community Life & Culture","paragraphs":["Veyvah is home to approximately 500 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and authentic cultural traditions that have been preserved in their most natural form."]},{"heading":"Island Life","paragraphs":["Daily life on Veyvah follows traditional patterns centered around fishing, family, and community activities. The island maintains an authentic atmosphere where visitors can experience genuine Maldivian culture and customs in their most unspoiled, traditional setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this authentic island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Veyvah has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and authentic cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Veyvah Island?","answer":"Regular ferry services are also available from Male and nearby islands in Meemu Atoll."},{"question":"What is the best time to visit Veyvah?","answer":"The best time to visit Veyvah is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more authentic atmosphere."},{"question":"What accommodation options are available on Veyvah?","answer":"Veyvah offers various budget-friendly accommodations including family guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in an authentic setting."},{"question":"What makes Veyvah a hidden gem?","answer":"Veyvah is considered a hidden gem due to its remote location, pristine natural environment, and authentic cultural experiences. The island offers unspoiled beaches, excellent marine life, and genuine local interactions away from tourist crowds, making it perfect for adventurous travelers seeking authentic experiences."}],"island_nearby_slugs":["kolhufushi","muli","maduvvaree","raimmandhoo","dhiggaru","naalaafushi"]}'::jsonb
